import sys

def schedule_brute(tasks, n):
    if not tasks: return 0
    cnt = [0] * 26
    for t in tasks:
        cnt[ord(t) - 65] += 1
    mx = max(cnt)
    cnt_mx = sum(1 for c in cnt if c == mx)
    return max(len(tasks), (mx - 1) * (n + 1) + cnt_mx)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    m = int(data[0]); gap = int(data[1])
    tasks = data[2:2 + m]
    print(schedule_brute(tasks, gap))

